"""Generate the finite TypeScript command vocabulary from its Python owner."""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from aiko_pet.application.room_contracts import (  # noqa: E402
    PROTOCOL_VERSION,
    ROOM_COMMANDS,
)


def main() -> None:
    target = ROOT / "web/src/bridge/commands.ts"
    target.write_text(
        "// Generated by scripts/export_room_contracts.py.\n"
        f"export const roomProtocol = {PROTOCOL_VERSION} as const;\n"
        f"export const roomCommands = {json.dumps(sorted(ROOM_COMMANDS))} as const;\n"
        "export type RoomCommandName = typeof roomCommands[number];\n",
        encoding="utf8",
    )


if __name__ == "__main__":
    main()
